/**
 * ======================================================================
 * 【基本说明】：
 * MobileIMSDK-Web版服务端的错误码工厂类，目的仅是为了方便错误码的使用而已。
 * 错误码详见code.js文件中的定义。
 * ======================================================================
 */


// 服务端返回的错误码：客户端的连接已成功认证(此常量仅用于MobileIMSDK-Web版中，与MobileIMSDK-APP版暂无关联)
const CODE_AUTHED = 100;
// 服务端返回的错误码：客户端的连接未认证(此常量仅用于MobileIMSDK-Web版中，与MobileIMSDK-APP版暂无关联)
const CODE_UNAUTHED = 101;

var ErrorCode = require('./error-code');
//var code = require('./code');


// 生成“未认证”的错误信息对象（socket.io v1.0后的版本中，官方推荐的连接认证最佳实践是通过服务端的error事件来处理的）
exports.CodeUnauthed = new ErrorCode(CODE_UNAUTHED, 'Connection not authorized!');

// 生成“认证成功”的错误信息对象（socket.io v1.0后的版本中，官方推荐的连接认证最佳实践是通过服务端的error事件来处理的）
exports.CodeAuthed = new ErrorCode(CODE_AUTHED, 'Authorized success!');

